async getOriginalMessage() {
  if (this.#originalMessage) {
    return this.#originalMessage;
  }

  // Check if this msgHdr belongs to a message, which is actually an attachment
  // of an outer message.
  const parentMsgInfo = getParentMsgInfo(this.#msgHdr);
  if (parentMsgInfo) {
    const msgHdrProcessor = new MsgHdrProcessor(parentMsgInfo.msgHdr);
    let partName = parentMsgInfo.partName;

    // The returned partName may need to be adjusted for jsmime x-ray vision,
    // which needs nested messages to be identified by a $ in the partName.
    if (partName.split(".").length > 2) {
      const attachments = await msgHdrProcessor.getAttachmentParts({
        includeNestedAttachments: true,
      });
      const adjustedPartNames = new Map(
        attachments.map(attachment => [
          attachment.partNum.replaceAll("$.", ".1."),
          attachment.partNum,
        ])
      );
      // Convert 1.2.1.3 to 1.2$.3, if 1.2$.3 exists.
      if (adjustedPartNames.has(partName)) {
        partName = adjustedPartNames.get(partName);
      }
    }

    const attachment = await msgHdrProcessor.getAttachmentPart(partName, {
      includeRaw: true,
    });
    this.#originalMessage = attachment.body;
    return this.#originalMessage;
  }

  const msgUri = this.msgUri;
  const headersOnly = this.#bodyFormat == "none";
  const service = MailServices.messageServiceFromURI(msgUri);

  // Setup a connection timeout of 20s, to be able to fail if streaming stalls.
  let connectionSuccess = false;
  const connectionPromise = Promise.withResolvers();
  const connectionTimeout = setTimeout(() => {
    if (!connectionSuccess) {
      connectionPromise.reject(
        new ExtensionError(
          `Error while streaming message <${msgUri}>: Timeout`
        )
      );
    }
  }, 20000);

  const messagePromise = new Promise((resolve, reject) => {
    const streamlistener = {
      _data: [],
      _carry: "",
      _stream: null,
      _headersDoneEarly: false,
      onDataAvailable(aRequest, aInputStream, aOffset, aCount) {
        if (!this._stream) {
          this._stream = Cc[
            "@mozilla.org/scriptableinputstream;1"
          ].createInstance(Ci.nsIScriptableInputStream);
          this._stream.init(aInputStream);
        }
        const chunk = this._stream.read(aCount);

        // The data needs to be read, otherwise the UI will flash the message,
        // if it is currently viewed. We aborted the request and we should get
        // here at most one more time after resolving early.
        if (this._headersDoneEarly) {
          return;
        }

        if (headersOnly) {
          // The specs require \r\n\r\n to separate headers and body, but we have seen \n\n in the
          // wild as well (for example local messages).
          const boundaryTestData = `${this._carry}${chunk}`;
          const headerEndMatch = boundaryTestData.match(/\r?\n\r?\n/);
          if (headerEndMatch) {
            this._data.push(
              boundaryTestData.slice(
                this._carry.length,
                headerEndMatch.index + headerEndMatch[0].length
              )
            );
            this._headersDoneEarly = true;
            try {
              aRequest.cancel(Cr.NS_BINDING_ABORTED);
            } catch {
              // Cancel could fail if the underlying stream does not support cancellation. This
              // has been observed with our NNTP test server.
              // TODO: Fix the test server to support cancellation and remove this catch.
            }
            return;
          }
          // Keep last 3 bytes for the next boundary check.
          this._carry = boundaryTestData.slice(-3);
        }

        this._data.push(chunk);
      },
      onStartRequest() {
        connectionSuccess = true;
      },
      onStopRequest(request, status) {
        if (this._headersDoneEarly || Components.isSuccessCode(status)) {
          if (!this._data) {
            reject(
              new ExtensionError(
                `Error while streaming message <${msgUri}>: No data`
              )
            );
          }
          resolve(this._data.join(""));
        } else {
          reject(
            new ExtensionError(
              `Error while streaming message <${msgUri}>: Status ${status}`
            )
          );
        }
      },
      QueryInterface: ChromeUtils.generateQI([
        "nsIStreamListener",
        "nsIRequestObserver",
      ]),
    };

    // This is not using aConvertData and returns the raw unprocessed message.
    service.streamMessage(
      msgUri,
      streamlistener,
      null, // aMsgWindow
      null, // aUrlListener
      false, // aConvertData
      "" //aAdditionalHeader
    );
  });

  try {
    this.#originalMessage = await Promise.race([
      connectionPromise.promise,
      messagePromise,
    ]);
  } finally {
    // Clean up pending connectionPromise and connectionTimeout.
    clearTimeout(connectionTimeout);
    connectionPromise.resolve();
  }
  return this.#originalMessage;
}

